import type { Pregunta } from '../quiz';

// Nivel BÁSICA (español) · 142 preguntas: definiciones y conceptos centrales de cada tema.
// Convención: la PRIMERA opción es siempre la correcta (en pantalla se mezclan al azar).
// Las cuatro opciones tienen largo parecido y las incorrectas son conceptos reales de la guía.
// Criterio 2026-11: distractores plausibles (errores comunes, tipo vs. modalidad, nivel vecino), sin opciones absurdas.

export const basica: Pregunta[] = [
  // ── El modelo ecológico ──
  { p: 'Según el modelo ecológico, ¿por qué la violencia de género es un problema social?', o: ['Porque se explica por factores sumados en varios niveles', 'Porque ocurre sobre todo en barrios pobres y sin trabajo', 'Porque casi todos los agresores crecieron con violencia', 'Porque afecta a muchas parejas distintas a la vez'], e: 'El modelo explica la violencia por factores combinados en distintos niveles. La pobreza o una infancia violenta son factores de riesgo, no explicaciones suficientes, y que afecte a muchas parejas no la vuelve social: lo social es su raíz en la desigualdad de poder.', f: 'Su conclusión fue que no existe una causa única: la violencia aparece cuando se combinan factores de distintos niveles.', t: 'modelo-ecologico' },
  { p: '¿Quién propuso mirar el desarrollo de una persona dentro de ambientes que se contienen unos a otros, como círculos?', o: ['Urie Bronfenbrenner', 'Lori L. Heise', 'Lenore E. Walker', 'Marsha M. Linehan'], e: 'Bronfenbrenner (1979). Heise llevó esa idea a la violencia contra las mujeres (1998); Walker describió el ciclo de la violencia y Barudy pensó la familia como sistema abierto.', f: 'El psicólogo Urie Bronfenbrenner propuso en 1979 mirar el desarrollo de una persona dentro de los ambientes en los que vive, como si fueran círculos uno dentro del otro.', t: 'modelo-ecologico' },
  { p: '¿Para qué sirve un modelo como el ecológico?', o: ['Para ordenar un problema complejo y ver cómo se conectan sus partes', 'Para predecir qué personas van a ejercer violencia en el futuro', 'Para dar una explicación única que valga para todos los casos', 'Para clasificar a las víctimas según su nivel de riesgo'], e: 'Un modelo simplifica para entender, como un mapa. No predice quién va a ejercer violencia ni da una sola causa: justamente muestra que hay muchas.', f: 'Un modelo es una forma simplificada de representar algo complejo, como un mapa: no muestra cada piedra del camino, pero ayuda a entender cómo se conectan las partes y por dónde ir.', t: 'modelo-ecologico' },
  { p: '¿Cuáles son los cuatro niveles del modelo ecológico que adoptó la OMS?', o: ['Individual, relacional, comunitario y social', 'Micro, meso, exo y macrosistema', 'Individual, familiar, escolar y laboral', 'Físico, psicológico, sexual y económico'], e: 'Individual, relacional, comunitario y social (OMS, 2002, a partir de Heise). Micro, meso, exo y macro son los sistemas de Bronfenbrenner; físico, psicológico, sexual y económico son tipos de violencia.', f: 'Esta guía los agrupa como microsocial (individual y relacional), mesosocial (comunitario) y macrosocial (social):', t: 'modelo-ecologico' },
  { p: 'Un grupo de amigos festeja que uno de ellos le revise el celular a su novia. ¿En qué nivel del modelo está ese factor?', o: ['Relacional', 'Individual', 'Comunitario', 'Social'], e: 'Los amigos son vínculos cercanos: nivel relacional. Sería social si fuera una idea extendida en toda la cultura, y comunitario si fuera una norma del barrio o la escuela.', f: 'Relacional: los vínculos más cercanos: la pareja, la familia, los amigos.', t: 'modelo-ecologico' },
  { p: 'En un barrio, los vecinos escuchan gritos en una casa y piensan que “en casa ajena no hay que meterse”. ¿Qué nivel del modelo muestra esto?', o: ['Comunitario', 'Relacional', 'Social', 'Histórico'], e: 'Es una norma del barrio: nivel comunitario (mesosocial). No es relacional porque no son los vínculos cercanos de la pareja, y no es social porque no se trata de toda la sociedad.', f: 'Comunitario: los vecinos escuchan los gritos, pero nadie dice nada; en el barrio no hay un lugar donde consultar.', t: 'modelo-ecologico' },

  // ── Violencia de género ──
  { p: '¿Qué ley argentina define la violencia contra las mujeres y enumera sus tipos y modalidades?', o: ['La Ley 26.485, de 2009', 'La Ley 26.791, de 2012', 'La Ley 27.736, de 2023', 'La Ley 24.632, de 1996'], e: 'La 26.485 (2009). La 26.791 incorporó el femicidio al Código Penal; la 27.736 sumó la violencia digital a la 26.485; la 24.632 aprobó la Convención de Belém do Pará.', f: 'La ley argentina que protege a las mujeres de la violencia es la Ley 26.485 (2009).', t: 'violencia-de-genero' },
  { p: 'Un empujón que no deja marcas, ¿es violencia física según la ley?', o: ['Sí: alcanza con que produzca dolor, daño o riesgo de producirlo', 'No: para ser física tiene que dejar una lesión visible', 'Depende: tiene que repetirse varias veces en el tiempo', 'Depende: tiene que ocurrir dentro de una pareja'], e: 'La ley define la violencia física como la que produce dolor, daño o riesgo de producirlo. No hace falta una lesión visible ni que se repita, y puede ejercerla cualquier persona.', f: 'Física: la que se ejerce contra el cuerpo y produce dolor, daño o riesgo de producirlo.', t: 'violencia-de-genero' },
  { p: 'Él le da “lo justo” para la comida cada semana y le pide los tickets de todo lo que compra. ¿Qué tipo de violencia es?', o: ['Económica', 'Simbólica', 'Doméstica', 'Institucional'], e: 'Limitar el dinero y controlar los gastos es violencia económica (art. 5). “Doméstica” no es un tipo sino una modalidad: dice dónde ocurre, no qué se daña.', f: 'Económica y patrimonial: la que controla los recursos de la otra persona.', t: 'violencia-de-genero' },
  { p: 'Una publicidad muestra siempre a mujeres limpiando y a varones decidiendo. Según los tipos del art. 5, ¿qué violencia es?', o: ['Simbólica', 'Psicológica', 'Mediática', 'Política'], e: 'Reproducir estereotipos que naturalizan la subordinación es violencia simbólica. Mediática no es un tipo sino una modalidad (art. 6): también aplica, porque se difunde en medios.', f: 'La violencia simbólica es la más difícil de ver, porque no deja marcas y está en todas partes: en los medios, en la publicidad, en la escuela, en la música.', t: 'violencia-de-genero' },
  { p: 'Un desconocido le dice comentarios sexuales a una mujer en el colectivo. ¿Qué modalidad de violencia es?', o: ['Espacio público', 'Sexual', 'Institucional', 'Doméstica'], e: 'Es la modalidad en el espacio público (Ley 27.501). Sexual es un tipo de violencia, no una modalidad; las modalidades dicen dónde ocurre.', f: 'En el espacio público: conductas o expresiones con connotación sexual en la calle, el transporte o los comercios que afectan la dignidad o la libertad de circular.', t: 'violencia-de-genero' },
  { p: 'En el iceberg de la violencia, ¿cuál de estas formas está en la parte visible, sobre el agua?', o: ['Gritar e insultar', 'Humillar y despreciar', 'Culpabilizar', 'Controlar'], e: 'Gritar, insultar y amenazar están en la punta. Humillar, despreciar y culpabilizar están bajo la superficie, y controlar, en la base de las formas sutiles.', f: 'Visible · formas explícitas', t: 'violencia-de-genero' },
  { p: 'Un chiste machista no es lo mismo que un golpe. Entonces, ¿por qué el iceberg lo incluye?', o: ['Porque ayuda a que el desprecio y el control parezcan normales', 'Porque la ley lo castiga igual que una agresión física', 'Porque casi siempre termina en violencia física', 'Porque es la forma de violencia más frecuente'], e: 'Las formas sutiles sostienen a las visibles porque las naturalizan. No se castigan igual ni llevan necesariamente a la violencia física.', f: 'Un chiste machista no es lo mismo que un golpe, pero ayuda a que el control y el desprecio parezcan normales.', t: 'violencia-de-genero' },
  { p: '¿Qué distingue a un femicidio de otros asesinatos de mujeres?', o: ['Que la matan por el hecho de ser mujer', 'Que el agresor es su pareja o su expareja', 'Que ocurre dentro de la casa de la víctima', 'Que antes hubo una denuncia por violencia'], e: 'Lo define el motivo de género. Puede cometerlo una pareja, un familiar, un conocido o un desconocido, y no hace falta que haya habido denuncia ni que ocurra en la casa.', f: 'el asesinato de una mujer cometido por un varón por el hecho de ser mujer', t: 'violencia-de-genero' },

  // ── Ciclo de la violencia ──
  { p: '¿Cuántas fases tenía el ciclo en el modelo original de Walker, y cuántas en la versión que usa esta guía?', o: ['Tres y cuatro', 'Cuatro y tres', 'Cuatro en los dos casos', 'Tres y cinco'], e: 'Walker (1979) describió tres fases. La versión de divulgación que usa la guía tiene cuatro, porque separa el arrepentimiento de la calma.', f: 'La versión de cuatro fases que usamos acá, muy difundida, separa ese arrepentimiento (“temor a perder la relación”) de la calma que viene después (“luna de miel”).', t: 'ciclo-de-la-violencia' },
  { p: 'En la versión de cuatro fases, ¿cómo se llama la etapa de calma en la que todo parece estar bien?', o: ['Luna de miel', 'Temor a perder la relación', 'Acumulación de tensión', 'Reconciliación'], e: 'Es la luna de miel. El temor a perder la relación es la etapa de arrepentimiento y promesas que llega después del estallido.', f: 'un período de romance en el que todo parece estar bien', t: 'ciclo-de-la-violencia' },
  { p: 'Ella cuida cada palabra y deja de ver a sus amigas para que él no se enoje. ¿Qué fase del ciclo es?', o: ['Acumulación de tensión', 'Luna de miel', 'Temor a perder la relación', 'Período violento'], e: 'Es la acumulación de tensión: ella siente que camina sobre cáscaras de huevo para evitar un estallido.', f: 'Ella siente que tiene que “caminar sobre cáscaras de huevo” para no provocar un estallido.', t: 'ciclo-de-la-violencia' },
  { p: 'Después de un estallido, él pide perdón, trae flores y promete ir a terapia. Según el ciclo, ¿qué significa?', o: ['Que es parte del ciclo, y no quiere decir que la violencia terminó', 'Que el ciclo se cortó, porque él reconoció lo que hizo', 'Que la relación entra en la fase de acumulación de tensión', 'Que la violencia fue un episodio aislado'], e: 'El arrepentimiento y las promesas son una fase del mismo ciclo. Reconocer el daño es valioso, pero por sí solo no corta el ciclo.', f: 'Las etapas de calma y de promesas de cambio forman parte del mismo ciclo: no significan que la violencia terminó.', t: 'ciclo-de-la-violencia' },
  { p: 'Según Walker, ¿qué suele pasar con el ciclo a medida que se repite?', o: ['Los estallidos son más frecuentes y la luna de miel, más corta', 'Los estallidos se espacian y la luna de miel se alarga', 'Las fases duran lo mismo a lo largo del tiempo', 'La tensión baja, porque la pareja aprende a manejarla'], e: 'El ciclo tiende a acelerarse: la tensión aparece más rápido, los estallidos son más frecuentes y graves, y la luna de miel se acorta o desaparece.', f: 'con el tiempo, el ciclo suele cambiar de ritmo', t: 'ciclo-de-la-violencia' },

  // ── Efectos de la violencia de género en las infancias ──
  { p: 'Un niño ve cómo su padre golpea a su madre, aunque a él no le pegan. ¿Qué es él?', o: ['Víctima indirecta de esa violencia', 'Testigo, pero no víctima', 'Víctima directa de esa violencia', 'Víctima recién si muestra señales'], e: 'Es víctima indirecta: presenciar la violencia entre quienes lo crían también lo daña, aunque no muestre señales. Sería víctima directa si la violencia se dirigiera a él.', f: 'Indirecta: cuando presencian la violencia entre los adultos que los crían, o cuando viven en un ambiente donde el abuso de poder se justifica.', t: 'efectos-en-las-infancias' },
  { p: '¿Por qué el daño es mayor cuando la violencia ocurre en la casa?', o: ['Porque viene de quienes deberían cuidarlos y protegerlos', 'Porque en la casa la violencia es más frecuente que afuera', 'Porque los chicos pasan más horas ahí que en otro lugar', 'Porque en la casa nadie más se entera de lo que pasa'], e: 'Es un trauma relacional: quien daña es quien debería dar seguridad. La frecuencia o las horas no explican la gravedad, y muchas veces otras personas sí se enteran.', f: 'Cuando la violencia ocurre justamente ahí, el daño es doble: quien agrede suele ser una figura central para ellos (muchas veces, el padre), y la madre, que suele ser su refugio, puede estar asustada o lastimada.', t: 'efectos-en-las-infancias' },
  { p: 'Asumir roles de cuidado o protección que no corresponden a la edad se llama…', o: ['Parentalización', 'Normalización', 'Regresión', 'Socialización'], e: 'Es la parentalización: niñas y niños que cuidan o protegen como si fueran adultos.', f: 'Parentalización: asumir roles que no les corresponden, como cuidar a los hermanos menores, consolar a la madre o intentar protegerla poniéndose en el medio.', t: 'efectos-en-las-infancias' },
  { p: 'Volver a mojar la cama cuando ya se había logrado controlarlo es una conducta…', o: ['Regresiva', 'Agresiva', 'Parentalizada', 'Depresiva'], e: 'Las conductas regresivas (actuar como de menor edad, enuresis, encopresis) son una de las señales posibles.', f: 'Conductas regresivas: volver a comportarse como de menor edad.', t: 'efectos-en-las-infancias' },
  { p: '¿Qué dice la guía sobre haber crecido con violencia?', o: ['Que es un factor de riesgo, no un destino', 'Que lleva en la mayoría de los casos a repetirla', 'Que deja secuelas que no se pueden revertir', 'Que afecta poco si la violencia no era contra ellos'], e: 'Es un factor de riesgo, pero pocas personas que crecieron con violencia la ejercen después (Fernández-Montalvo y Echeburúa, 1997). Las secuelas se pueden trabajar, y ser víctima indirecta también daña.', f: 'Fernández-Montalvo y Echeburúa (1997) observan que pocas personas que crecieron con violencia la ejercen en la adultez, aunque sí quedan más vulnerables.', t: 'efectos-en-las-infancias' },
  { p: '¿Qué es el trauma relacional?', o: ['Que la seguridad del vínculo se rompa por la misma persona que cuida', 'Un trauma causado por una pareja violenta en la adultez', 'El daño que deja presenciar una pelea entre desconocidos', 'La dificultad para vincularse después de un hecho traumático'], e: 'Sheinberg y True (2008): la ruptura de la seguridad que debería dar el vínculo, causada por las mismas personas adultas que deberían darla.', f: 'Sheinberg y True (2008), en un trabajo publicado en la revista de terapia familiar Family Process, llaman a esto trauma relacional: la ruptura de la seguridad emocional o física que debería dar el vínculo con madres, padres o personas cuidadoras, causada por esas mismas personas adultas.', t: 'efectos-en-las-infancias' },

  // ── Igualdad y no discriminación ──
  { p: 'Ser niña, mujer, pobre y vivir con VIH: cuando se cruzan estas condiciones…', o: ['Se agravan las violaciones de derechos, porque los riesgos se suman', 'Prevalece la condición más grave y las demás pasan a segundo plano', 'Cada condición se protege con una ley distinta, por separado', 'Se protege la condición más visible, que suele ser el género'], e: 'Es la interseccionalidad: el cruce de condiciones acentúa las violaciones de derechos. Por eso hay que mirarlas juntas, no por separado ni elegir una.', f: 'Cada una de esas condiciones ya la expone a ser discriminada; juntas, no se suman simplemente: se potencian.', t: 'igualdad-y-no-discriminacion' },
  { p: '¿Qué deben hacer los Estados frente a la violencia contra las mujeres?', o: ['Prevenir, investigar y sancionar con debida diligencia', 'Actuar cuando la víctima presenta una denuncia formal', 'Intervenir en los casos en que hay violencia física', 'Promover la mediación entre las partes'], e: 'Los Estados deben prevenir, investigar y sancionar con debida diligencia, aunque no haya denuncia ni violencia física. La mediación está prohibida en estos casos.', f: 'Quiere decir hacer todo lo razonable para evitar la violencia y, cuando ocurre, investigarla y sancionarla.', t: 'igualdad-y-no-discriminacion' },
  { p: '¿Qué sigla corresponde a la convención sobre la eliminación de la discriminación contra la mujer?', o: ['CEDAW', 'CADH', 'OMS', 'DADDH'], e: 'CEDAW: Convención sobre la eliminación de todas las formas de discriminación contra la mujer.', f: 'La CEDAW (1979) es la convención de Naciones Unidas contra la discriminación de la mujer.', t: 'igualdad-y-no-discriminacion' },
  { p: '¿Cómo identifica la CIDH a las mujeres?', o: ['Como un sector históricamente discriminado', 'Como un sector con igualdad formal ya alcanzada', 'Como una minoría que necesita cupos', 'Como un grupo vulnerable por razones biológicas'], e: 'La CIDH las identifica como un sector tradicionalmente discriminado. Las mujeres no son una minoría, y su vulnerabilidad es social, no biológica.', f: 'La CIDH reconoce a las mujeres como un sector tradicionalmente discriminado en el ejercicio de sus derechos humanos, y advierte que esa discriminación afecta de manera profunda y generalizada su vida: el trabajo, la educación, la salud, la participación política y la seguridad.', t: 'igualdad-y-no-discriminacion' },
  { p: 'Para la CEDAW, la violencia dirigida contra la mujer porque es mujer…', o: ['Queda incluida dentro de la discriminación', 'Se trata en un tratado aparte, no en la CEDAW', 'Es un tema que la CEDAW deja a cada país', 'Cuenta cuando hay intención de dañar'], e: 'La CEDAW (Recomendación General 19) incluye en la discriminación la violencia basada en el sexo. Belém do Pará la desarrolla después, pero no la saca de la CEDAW, y no hace falta intención.', f: 'El Comité de la CEDAW aclaró además (Recomendación General 19, 1992) que la discriminación incluye la violencia basada en el sexo: la que se dirige contra una mujer porque es mujer, o la que afecta a las mujeres mucho más que a los varones.', t: 'igualdad-y-no-discriminacion' },

  // ── Legislación ──
  { p: 'La CEDAW dice que los derechos humanos son interdependientes e indivisibles. ¿Qué significa?', o: ['Que no se puede garantizar un derecho a costa de otro', 'Que cada país elige qué derechos cumplir primero', 'Que se garantizan de a poco, según los recursos', 'Que valen cuando están en la Constitución'], e: 'Interdependientes e indivisibles: no se garantizan unos sacrificando otros. No dependen de que cada país elija ni de que estén en la Constitución.', f: 'Los derechos humanos son interdependientes e indivisibles: no se puede garantizar unos a costa de otros.', t: 'legislacion' },
  { p: '¿Qué afirma la Convención de Belém do Pará sobre la violencia contra la mujer?', o: ['Que es una violación de los derechos humanos', 'Que es ante todo un problema de salud pública', 'Que es un problema de algunos países de la región', 'Que puede abordarse con mediación familiar'], e: 'Belém do Pará la define como una violación de los derechos humanos. La mirada de salud pública es la de la OMS, y la mediación está excluida en estos casos.', f: 'afirman que la violencia contra la mujer es una violación de los derechos humanos', t: 'legislacion' },
  { p: 'Según Belém do Pará, la violencia contra la mujer…', o: ['Atraviesa clases, culturas, edades y religiones', 'Es más frecuente donde hay pobreza y menos educación', 'Ocurre sobre todo en zonas rurales', 'Se concentra en ciertas edades y culturas'], e: 'La Convención dice que trasciende todos los sectores: clase, raza, cultura, edad, ingresos, educación y religión. El contexto puede influir, pero no la limita a ningún grupo.', f: 'reconocen que atraviesa a todos los sectores: cualquier clase social, origen, nivel de ingresos, cultura, educación, edad o religión', t: 'legislacion' },
  { p: '¿Cuál de estos es un objetivo de la Ley 26.485?', o: ['Que el Estado elimine la discriminación y garantice una vida sin violencia', 'Que la violencia de género sea un delito penal específico', 'Que los casos se resuelvan en juzgados de familia mediante acuerdos', 'Que exista un registro único de agresores en todo el país'], e: 'La ley busca eliminar la discriminación y garantizar el derecho a una vida sin violencia. No crea delitos penales (el femicidio está en el Código Penal) y prohíbe la mediación.', f: 'Entre otras cosas, eliminar la discriminación entre mujeres y varones; garantizar el derecho a vivir sin violencia; cambiar los patrones culturales que sostienen la desigualdad; asegurar el acceso a la justicia y la asistencia integral; y, desde 2023, proteger los derechos de las mujeres en el espacio digital.', t: 'legislacion' },
  { p: '“Toda mujer tiene derecho a una vida libre de violencia, tanto en el ámbito público como en el privado”. ¿De qué norma es esta frase?', o: ['La Convención de Belém do Pará', 'La CEDAW', 'La Ley 26.485', 'La Declaración de la ONU de 1993'], e: 'Es el art. 3 de Belém do Pará (1994). La CEDAW trata la discriminación, y la Ley 26.485 retoma ese derecho para la Argentina.', f: 'Su idea central está en el art. 3', t: 'legislacion' },
  { p: '¿Qué es la violencia indirecta según la Ley 26.485?', o: ['Una práctica o norma que pone a la mujer en desventaja frente al varón', 'Una agresión física cometida por una tercera persona', 'La que sufren los hijos al presenciar la violencia contra su madre', 'Un daño que se produce sin intención de dañar'], e: 'La ley llama indirecta a toda conducta, acción, omisión, disposición, criterio o práctica que pone a la mujer en desventaja. Los hijos que presencian la violencia son víctimas indirectas, que es otro concepto.', f: '“Se considera violencia indirecta, a los efectos de la presente ley, toda conducta, acción, omisión, disposición, criterio o práctica discriminatoria que ponga a la mujer en desventaja con respecto al varón.”', t: 'legislacion' },

  // ── Micromachismos ──
  { p: '¿Quién acuñó el término “micromachismos” en los años 90?', o: ['Luis Bonino', 'Pierre Bourdieu', 'Maurice Godelier', 'Terry Real'], e: 'Godelier y Bourdieu estudiaron la dominación masculina en lo cotidiano; Luis Bonino los denominó “micromachismos” (mM) en los años 90.', f: 'El término micromachismos lo propuso en los años 90 el psicoterapeuta Luis Bonino, que trabaja en España.', t: 'micromachismos' },
  { p: 'Según Bonino, ¿qué buscan sobre todo los micromachismos?', o: ['Oponerse al cambio de las mujeres', 'Sojuzgar a la mujer por la fuerza', 'Humillarla en público ante otros', 'Controlar sus ingresos y sus bienes'], e: 'Son ejercicios sutiles y cotidianos del poder de dominio que buscan “no tanto sojuzgar como oponerse al cambio femenino”. Controlar los ingresos es violencia económica.', f: 'Son los más naturalizados, tanto por mujeres como por varones, y una de las formas más eficaces de resistencia al cambio.', t: 'micromachismos' },
  { p: '¿Cuántas categorías de micromachismos describe la guía?', o: ['Cuatro', 'Dos', 'Siete', 'Doce'], e: 'Utilitarios, encubiertos, de crisis y coercitivos.', f: 'Los cuatro tipos', t: 'micromachismos' },
  { p: 'No hacerse cargo de lo doméstico y delegarlo en la mujer es un micromachismo…', o: ['Utilitario', 'Encubierto', 'De crisis', 'Coercitivo'], e: 'Los utilitarios fuerzan la disponibilidad femenina aprovechando lo doméstico y el cuidado.', f: 'No hacerse cargo de lo doméstico.', t: 'micromachismos' },
  { p: '¿Contra qué atentan sobre todo los micromachismos?', o: ['La autonomía y la capacidad de elegir de las mujeres', 'La integridad física de las mujeres', 'El patrimonio y el salario de las mujeres', 'La participación política de las mujeres'], e: 'Son maniobras sutiles que restringen la autonomía y la capacidad de decidir. Los daños al cuerpo, al patrimonio o a la participación política corresponden a otros tipos de violencia.', f: 'Los micromachismos atentan, en distintos grados, contra la libertad, la autonomía y la capacidad de elegir de las mujeres.', t: 'micromachismos' },
  { p: 'Él decide qué se mira en la tele y cuándo se usa el auto, porque “el que paga, manda”. ¿Qué tipo de micromachismo es?', o: ['Coercitivo', 'Utilitario', 'De crisis', 'Encubierto'], e: 'Retener poder con la fuerza moral o económica es coercitivo. Utilitario es aprovecharse del trabajo doméstico de ella; de crisis, reaccionar cuando ella gana poder.', f: 'Usan la fuerza moral, psicológica o económica para imponer la propia voluntad.', t: 'micromachismos' },

  // ── Mitos del amor romántico y celos ──
  { p: 'Según la guía, ¿qué expresan los celos?', o: ['Miedo a perder al otro y deseo de poseerlo', 'La medida de cuánto se ama a alguien', 'Una forma de cuidar y proteger a la pareja', 'Una reacción que aparece cuando hay motivos'], e: 'Los celos expresan miedo a perder y deseo de posesión. No miden el amor ni son cuidado, y pueden aparecer sin ningún motivo real.', f: 'los celos limitan la libertad de la otra persona y no son una muestra de amor, sino de posesión', t: 'mitos-del-amor-romantico' },
  { p: '¿Qué plantea el mito de la media naranja?', o: ['Que sin pareja somos mitades incompletas', 'Que el amor verdadero dura para siempre', 'Que el amor todo lo puede', 'Que los opuestos se atraen'], e: 'La media naranja dice que estamos incompletos sin pareja. “Dura para siempre” y “todo lo puede” son otros mitos del amor romántico.', f: 'La idea de que existe una única persona destinada a completarnos, y que sin ella estamos incompletos', t: 'mitos-del-amor-romantico' },
  { p: '¿Qué es un mito, según la guía?', o: ['Una creencia compartida y sin fundamento que se presenta como verdad', 'Una idea minoritaria que casi nadie toma en serio hoy en día', 'Una mentira que alguien inventa a propósito para engañar', 'Una experiencia personal que se generaliza a todos los casos'], e: 'Un mito es una creencia sin fundamento que se presenta como verdad y que mucha gente comparte. No es una mentira deliberada ni una idea minoritaria: justamente por compartida tiene fuerza.', f: 'Un mito es una creencia que se presenta como una verdad absoluta, aunque no tenga fundamento.', t: 'mitos-del-amor-romantico' },
  { p: 'Revisar el celular de la pareja o decidir con quién habla, ¿qué es?', o: ['Violencia psicológica', 'Violencia económica', 'Violencia simbólica', 'Violencia física'], e: 'Controlar (revisar el celular, decidir con quién se habla o cómo vestirse) es violencia psicológica, aunque se lo llame "acuerdo".', f: 'Revisar el celular, pedir la ubicación todo el tiempo, decidir con quién se habla o cómo vestirse, aislar de las amistades o de la familia: todo eso es violencia psicológica, aunque se presente como “cuidado” o “interés”.', t: 'mitos-del-amor-romantico' },
  { p: '¿De quién es la responsabilidad de trabajar las inseguridades que hay detrás de los celos?', o: ['De quien siente los celos', 'De la pareja, que tiene que darle seguridad', 'De los dos por igual', 'De la pareja, evitando dar motivos'], e: 'Es de quien siente los celos. La pareja puede acompañar, pero no es su tarea dar pruebas ni cambiar su vida para evitar los celos del otro.', f: 'Trabajar esas inseguridades es responsabilidad de quien siente los celos, no de su pareja.', t: 'mitos-del-amor-romantico' },
  { p: 'Según la socialización diferencial, ¿qué se les enseñó tradicionalmente a los varones?', o: ['A no mostrar miedo ni tristeza', 'A pedir ayuda cuando algo les pasa', 'A priorizar el cuidado de los demás', 'A expresar el enojo con palabras'], e: 'Se les enseñó a ocultar el miedo y la tristeza. El cuidado de los demás se les asignó a las mujeres.', f: 'A los varones se los preparó para el éxito en el mundo público, para que su valor dependa de lo que logran afuera, y para no mostrar emociones de “debilidad”, como el miedo o la tristeza.', t: 'mitos-del-amor-romantico' },

  // ── Patriarcado y masculinidades ──
  { p: 'Según la guía, ¿por qué no puede hablarse de “empate” entre varones y mujeres frente al patriarcado?', o: ['Porque ellos conservan privilegios, aunque también los dañe', 'Porque el patriarcado no les causa daño a los varones', 'Porque los dos pierden lo mismo con el machismo', 'Porque la ley ya corrigió la desigualdad entre ambos'], e: 'El patriarcado también daña a los varones, pero eso no borra los privilegios que conservan. Por eso no hay empate.', f: 'Los varones conservan privilegios concretos: en promedio, ganan más, tienen más acceso a cargos de poder, cargan con menos tareas de cuidado y su violencia muchas veces se naturaliza.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según Kali Holloway, ¿cuáles son las palabras más dañinas que recibe un niño?', o: ['“Sé un hombre”', '“Portate bien”', '“Hacé caso”', '“Prestá atención”'], e: 'Holloway (2015): “la masculinidad está matando a los hombres”. El mandato “sé un hombre” obliga a demostrar constantemente lo que se es.', f: 'La periodista estadounidense Kali Holloway (2015) dice que una de las frases más dañinas que puede escuchar un chico es “sé un hombre”.', t: 'patriarcado-y-masculinidades' },
  { p: 'Según la guía, ¿desde qué edad los varones aprenden a ocultar lo que sienten?', o: ['Entre los 3 y los 5 años', 'Entre los 10 y los 12 años', 'Recién en la adolescencia', 'Recién en la adultez'], e: 'No tienen menos emociones: aprenden que es mejor no mostrarlas. La masculinización empieza en la primera infancia (Real, 1997).', f: 'Entre los 3 y los 5 años, muchos chicos ya ocultan lo que sienten', t: 'patriarcado-y-masculinidades' },
  { p: 'Según Terry Real, en comparación con las nenas, ¿cómo tratan los adultos a los bebés varones?', o: ['Les hablan y los reconfortan menos', 'Les atribuyen más necesidad de afecto', 'Los describen como más miedosos', 'Los alientan a mostrar lo que sienten'], e: 'Se les proyecta una masculinidad innata y menor necesidad de confort y afecto, aunque en realidad son más sensibles y expresivos. Ante el mismo bebé llorando, los adultos lo describieron como “colérico” si creían que era varón y “miedoso” si creían que era nena. Los recortes emocionales empiezan en el momento más vulnerable (Real, 1997).', f: 'creen que necesitan menos consuelo y menos afecto', t: 'patriarcado-y-masculinidades' },
  { p: 'En la crianza tradicional de los varones, ¿qué emoción suele tener “permiso”?', o: ['El enojo', 'La tristeza', 'El miedo', 'La ternura'], e: 'Se les permite el enojo y se les enseña a ocultar el miedo, la tristeza y la ternura. Por eso mucho dolor sale como enojo, consumo o exceso de trabajo.', f: 'Esa forma de expresar el dolor muchas veces esconde una depresión que no se diagnostica: en un varón, el enojo constante, el consumo de alcohol o trabajar sin parar pueden ser formas de esa depresión.', t: 'patriarcado-y-masculinidades' },
  { p: '¿Cómo llama Stephanie Coontz al modelo de hombre que transmiten los medios?', o: ['Mística masculina', 'Muerte espiritual', 'Víctimas coléricas', 'Código masculino'], e: 'La “mística masculina”: hombres emocionalmente desmembrados, con pánico a mostrar debilidad. “Muerte espiritual” es de Holloway; el “código masculino”, de Marvin Allen.', f: 'La historiadora Stephanie Coontz llama a esto la “mística masculina”: varones emocionalmente “desarmados”, con pánico a mostrar debilidad.', t: 'patriarcado-y-masculinidades' },

  // ── Violencia en el fútbol ──
  { p: 'Según la guía, la violencia en el fútbol…', o: ['No se reduce a las barras: involucra a muchos actores', 'Se concentra en los sectores más pobres', 'Es parte del folklore del fútbol argentino', 'Se resuelve con más presencia policial'], e: 'Involucra a hinchas, dirigentes, medios, policía y política. No es propia de los pobres, llamarla folklore la legitima, y más policía sin profesionalizar puede agravarla.', f: 'no es un problema solo de las barras ni solo de la policía', t: 'violencia-en-el-futbol' },
  { p: '¿Por qué la guía dice que la violencia en el fútbol se puede prevenir?', o: ['Porque se aprende y se reproduce en la cultura', 'Porque la cometen pocas personas identificables', 'Porque depende de la pasión, que se puede canalizar', 'Porque se controla con el derecho de admisión'], e: 'Lo que se aprende se puede desaprender. Reducirla a unos pocos o a la pasión deja afuera sus causas culturales, y la admisión sola no la previene.', f: 'La violencia se aprende y se reproduce culturalmente, dentro de un modelo patriarcal y machista: por eso se puede prevenir.', t: 'violencia-en-el-futbol' },
  { p: 'En la versión violenta del "aguante", ¿qué hay que hacer para pertenecer al grupo?', o: ['Pelear', 'Pagar una cuota', 'Alentar sin parar', 'Viajar a todos los partidos'], e: 'En la versión violenta, para pertenecer hay que pelear. Alentar sin parar es el otro sentido, no violento, del aguante.', f: 'En su versión violenta (que Garriga Zucal llama “aguante-violento”):', t: 'violencia-en-el-futbol' },
  { p: '¿De qué sectores sociales son las hinchadas, según Alabarces y Garriga Zucal?', o: ['De sectores populares y también de clase media', 'De los sectores más pobres, sobre todo', 'De jóvenes sin trabajo ni estudio, sobre todo', 'De dirigentes y sus allegados, sobre todo'], e: 'Hay hinchas de sectores populares y de clase media. La idea de que la violencia es cosa de pobres o de jóvenes sin futuro es un prejuicio.', f: '“Es cosa de pobres.” Es un prejuicio frecuente, pero las hinchadas reúnen a personas de sectores populares y de clase media.', t: 'violencia-en-el-futbol' },
  { p: '¿Por qué no conviene etiquetar a alguien como “violento”?', o: ['Porque lo presenta como alguien que no puede cambiar', 'Porque es un término jurídico que requiere sentencia', 'Porque estigmatiza a toda su hinchada', 'Porque la responsabilidad es del grupo, no de las personas'], e: 'La etiqueta lo fija como si fuera su naturaleza. Hablar de conductas violentas permite pensar en el cambio sin quitarle responsabilidad.', f: 'No etiquetar a nadie como “violento”: esa etiqueta presenta a las personas como incapaces de cambiar.', t: 'violencia-en-el-futbol' },
  { p: 'Un periodista llama “folklore” a una pelea entre hinchadas. Según la guía, eso…', o: ['Ayuda a legitimar la violencia', 'La exagera y genera alarma innecesaria', 'La presenta como un delito común', 'Muestra la pasión propia del fútbol'], e: 'Llamarla folklore la presenta como algo normal y propio del fútbol, y así la legitima.', f: 'Desarmar lo que la legitima: la idea de que la violencia es “natural”, parte del folklore o de la pasión.', t: 'violencia-en-el-futbol' },

  // ── Diversidad sexual ──
  { p: '¿Qué es la identidad de género?', o: ['El sentir interno de cada persona sobre su género', 'La atracción que una persona siente por otras', 'Las características biológicas del cuerpo', 'Los roles que la sociedad espera de cada uno según su sexo'], e: 'Es el sentimiento interno y personal sobre el propio género; puede coincidir o no con el sexo asignado al nacer.', f: 'Es la vivencia interna de su propio género, que puede coincidir o no con el sexo asignado al nacer.', t: 'diversidad-sexual' },
  { p: '¿Qué es el sexo, según la guía?', o: ['Las características biológicas y fisiológicas', 'El sentimiento interno sobre el propio género', 'La atracción emocional hacia otras personas', 'Los roles que la sociedad le atribuye a cada uno'], e: 'Cromosomas, órganos reproductivos, hormonas y caracteres físicos.', f: 'Son las características biológicas (cromosomas, órganos, hormonas).', t: 'diversidad-sexual' },
  { p: '¿Qué es el género?', o: ['Una construcción social sobre qué es ser varón o mujer', 'Las características biológicas con las que se nace', 'La vivencia interna de cada persona sobre sí', 'La atracción que se siente hacia otras personas'], e: 'El género es una construcción social. Las características biológicas son el sexo, la vivencia interna es la identidad de género y la atracción es la orientación sexual.', f: 'Por ejemplo, la idea de que los varones no lloran o de que el rosa es “de nenas” no viene de la biología: es una construcción social, y cambia según la época y el lugar.', t: 'diversidad-sexual' },
  { p: 'La atracción por personas de más de un género se llama…', o: ['Bisexualidad', 'Asexualidad', 'Heterosexualidad', 'Homosexualidad'], e: 'La bisexualidad es la atracción por personas de más de un género o sexo.', f: 'Bisexualidad: atracción por personas de más de un género.', t: 'diversidad-sexual' },
  { p: 'Una persona cuya identidad no se ajusta a las categorías de hombre o mujer es…', o: ['No binaria', 'Cisgénero', 'Asexual', 'Heterosexual'], e: 'No binario: la identidad no se ajusta a las categorías de hombre o mujer.', f: 'No binario: la identidad no se ajusta a las categorías de varón o mujer.', t: 'diversidad-sexual' },
  { p: '¿Qué es la diversidad sexual?', o: ['La variedad de identidades, orientaciones y expresiones', 'La variedad de orientaciones sexuales, sin incluir identidades', 'Otra forma de nombrar a la identidad de género de cada persona', 'La diferencia entre el sexo biológico y el género'], e: 'Es el conjunto de identidades, orientaciones y expresiones sexuales. No hay una única forma “correcta” de ser: la sexualidad humana es diversa.', f: 'La diversidad sexual es el conjunto de identidades, orientaciones y expresiones que existen entre las personas.', t: 'diversidad-sexual' },
  { p: '¿Qué ley reconoció el matrimonio igualitario en Argentina?', o: ['La Ley 26.618', 'La Ley 26.743', 'La Ley 26.485', 'La Ley 26.791'], e: 'La Ley 26.618 de Matrimonio Igualitario (2010).', f: 'Ley 26.618 de Matrimonio Igualitario.', t: 'diversidad-sexual' },

  // ── Entendimiento de la ira ──
  { p: '¿Qué “beneficio” inmediato tiene la ira?', o: ['Alivia el estrés por un rato', 'Ayuda a que el otro entienda lo que nos pasa', 'Pone límites que los demás después respetan', 'Resuelve el problema que la provocó'], e: 'Alivia la tensión por un rato, pero el malestar vuelve si no se trabaja. No resuelve el problema ni hace que el otro entienda: muchas veces lo pone a la defensiva.', t: 'entendimiento-de-la-ira' },
  { p: 'Según la guía, la ira muchas veces…', o: ['Oculta un dolor emocional', 'Es una reacción heredada de los padres', 'Lleva a la agresión si no se descarga', 'Es una emoción que conviene evitar'], e: 'Detrás del enojo suele haber dolor: miedo, tristeza, frustración. No se hereda, no lleva sola a la agresión y no hay que evitarla, sino aprender a expresarla.', t: 'entendimiento-de-la-ira' },
  { p: 'Gritar para que los demás nos presten atención, con el tiempo…', o: ['Los acostumbra y los pone a la defensiva', 'Hace que nos tomen más en serio', 'Les marca un límite que después respetan', 'Les muestra cuánto nos importa el tema'], e: 'Con el tiempo los demás se vuelven inmunes a los gritos y se defienden. Lo que se gana es miedo o distancia, no respeto.', t: 'entendimiento-de-la-ira' },
  { p: 'La guía dice que “el enojo lleva automáticamente a la agresión” es un mito. ¿Por qué?', o: ['Porque se puede frenar antes de que escale', 'Porque agreden sobre todo las personas impulsivas', 'Porque el enojo dura poco y se va solo', 'Porque descargarlo a tiempo evita la agresión'], e: 'El enojo se puede reconocer y frenar antes de llegar a la explosión. Descargarlo no lo resuelve, y no es cuestión de ser o no impulsivo.', t: 'entendimiento-de-la-ira' },
  { p: 'Expresar el enojo con respeto, sin culpar ni amenazar, es…', o: ['Asertividad', 'Pasividad', 'Pasivo-agresividad', 'Agresión'], e: 'Es la forma asertiva. La pasividad calla el enojo, la pasivo-agresividad lo expresa de forma indirecta y la agresión lo descarga sobre el otro.', t: 'entendimiento-de-la-ira' },
  { p: 'En la escala del enojo, ¿qué número es la calma total?', o: ['1', '5', '7', '10'], e: 'La escala va de 1 (calma total) a 10 (pérdida de control explosiva).', t: 'entendimiento-de-la-ira' },
  { p: '¿Cuál es la primera fase del ciclo de agresión del enojo?', o: ['Intensificación', 'Acumulación de tensión', 'Explosión', 'Post-explosión'], e: 'El ciclo de agresión tiene intensificación, explosión y post-explosión. Acumulación de tensión es una fase del ciclo de la violencia de Walker.', t: 'entendimiento-de-la-ira' },

  // ── El cerebro y las emociones ──
  { p: '¿Quién propuso el modelo de los tres cerebros?', o: ['Paul MacLean', 'Antonio Damasio', 'Daniel Goleman', 'Joseph LeDoux'], e: 'Paul MacLean. Damasio, Goleman y LeDoux también estudiaron las emociones, pero no propusieron ese modelo.', t: 'cerebro-y-emociones' },
  { p: 'En el modelo de los tres cerebros, ¿cuál es la parte más reciente y compleja?', o: ['La neocorteza', 'El complejo reptiliano', 'El sistema límbico', 'El tronco del encéfalo'], e: 'La neocorteza permite planificar y el pensamiento sistemático y lógico.', t: 'cerebro-y-emociones' },
  { p: '¿Qué es una emoción primaria?', o: ['La primera reacción ante un hecho', 'Una reacción a otra emoción', 'La emoción más intensa de una situación', 'La emoción que se muestra hacia afuera'], e: 'Es la primera reacción ante un hecho. La reacción a otra emoción es la secundaria, y no tiene que ver con la intensidad ni con mostrarla.', t: 'cerebro-y-emociones' },
  { p: 'Alguien se enoja y después siente culpa por haberse enojado. ¿Qué es esa culpa?', o: ['Una emoción secundaria', 'Una emoción primaria', 'Una ambivalencia emocional', 'Un pensamiento automático'], e: 'Es un “sentimiento de un sentimiento”: una reacción a la emoción primaria (el enojo). Las secundarias suelen causar más problemas porque encadenan emociones negativas. La ambivalencia, en cambio, son dos reacciones distintas ante el mismo hecho.', t: 'cerebro-y-emociones' },
  { p: 'Según la guía, las emociones comienzan en los sentidos. ¿Dónde se procesan?', o: ['En el sistema límbico', 'En la neocorteza', 'En el complejo reptiliano', 'En los órganos de los sentidos'], e: 'En el sistema límbico. La neocorteza piensa y regula, el reptiliano se ocupa de funciones básicas, y los sentidos solo captan la información.', t: 'cerebro-y-emociones' },
  { p: 'El ejercicio de cambio de enfoque alterna la atención entre…', o: ['La emoción y cada uno de los sentidos', 'Los recuerdos y los planes a futuro', 'Lo que uno siente y lo que siente el otro', 'Las tareas pendientes y el descanso'], e: 'Es un ejercicio de mindfulness de unos 10 minutos para separar la experiencia presente de lo emocional.', t: 'cerebro-y-emociones' },

  // ── Abordaje emocional (IFS) ──
  { p: '¿Quién creó el modelo IFS?', o: ['Richard Schwartz', 'Aaron Beck', 'Albert Ellis', 'Marsha Linehan'], e: 'Richard Schwartz creó el modelo de los Sistemas de la Familia Interna (IFS).', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿cómo se representa la mente?', o: ['Como una familia interna de partes', 'Como tres instancias: ello, yo y superyó', 'Como una cadena de pensamientos automáticos', 'Como tres cerebros superpuestos'], e: 'IFS ve la mente como una familia interna de partes. Ello, yo y superyó son de Freud; los pensamientos automáticos, de Beck; los tres cerebros, de MacLean.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿qué es la clave de la curación?', o: ['El Yo', 'El protector', 'El exiliado', 'El crítico'], e: 'El Yo integra las partes mediante compasión, curiosidad y conexión.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿qué buscan los protectores?', o: ['Evitar que el dolor se active', 'Sanar las heridas del pasado', 'Que el Yo tome el control', 'Expresar el dolor guardado'], e: 'Los protectores (gerentes y bomberos) buscan que el dolor de los exiliados no se active. Sanar es tarea del Yo.', t: 'abordaje-emocional-ifs' },
  { p: 'En el modelo IFS, ¿con qué cualidades integra el Yo a las partes?', o: ['Compasión, curiosidad y conexión', 'Control, orden y responsabilidad', 'Vigilancia, cautela y prudencia', 'Fuerza, firmeza y decisión'], e: 'Compasión, curiosidad y conexión son parte de las cualidades del Yo. Control, vigilancia o firmeza son más propias de las partes protectoras.', t: 'abordaje-emocional-ifs' },

  // ── Pensamientos automáticos ──
  { p: '¿Cómo aparecen los pensamientos automáticos?', o: ['Como un reflejo, sin razonarlos', 'Como conclusiones de un análisis rápido', 'Como recuerdos de cosas que pasaron', 'Como frases que alguien nos dijo'], e: 'Aparecen solos, como un reflejo, y se creen sin pensarlos. No son el resultado de un análisis.', t: 'pensamientos-automaticos' },
  { p: '¿Con qué terapia se asocia el concepto de pensamientos automáticos?', o: ['La terapia cognitiva de Beck', 'La terapia racional emotiva de Ellis', 'El psicoanálisis de Freud', 'El modelo IFS de Schwartz'], e: 'Es un concepto de la terapia cognitiva de Aaron Beck. Ellis, con un enfoque cercano, habla de creencias irracionales.', t: 'pensamientos-automaticos' },
  { p: 'Tras perder el empleo, pensar “soy un fracasado, nadie me va a contratar” es un ejemplo de…', o: ['Pensamiento automático', 'Emoción secundaria', 'Emoción primaria', 'Creencia racional'], e: 'Es un pensamiento automático: aparece solo y se cree sin cuestionarlo. Las emociones son lo que se siente, no lo que se piensa.', t: 'pensamientos-automaticos' },
  { p: '¿Qué herramienta ayuda a registrar los pensamientos automáticos?', o: ['El diario de pensamientos', 'La escala del enojo', 'El registro de señales del enojo', 'El ejercicio de cambio de enfoque'], e: 'El diario de pensamientos. La escala y las señales sirven para el enojo, y el cambio de enfoque, para regular una emoción.', t: 'pensamientos-automaticos' },
  { p: '¿Cuándo se escribe en el diario de pensamientos?', o: ['Cuando aparece una emoción desagradable', 'Al final del día, como un resumen', 'Cuando el malestar ya pasó del todo', 'Una vez por semana, para hacer balance'], e: 'Se anota en el momento o lo antes posible, cuando aparece la emoción. Si se deja para después, los pensamientos se olvidan.', t: 'pensamientos-automaticos' },
  { p: '¿De dónde vienen los pensamientos automáticos?', o: ['Se aprenden desde la infancia', 'Se heredan de los padres', 'Aparecen recién en la adultez', 'Los provoca el cansancio'], e: 'Se aprenden desde chicos, de lo que escuchamos y vivimos. Por eso también se pueden revisar.', t: 'pensamientos-automaticos' },

  // ── Distorsiones cognitivas ──
  { p: '¿Qué son las distorsiones cognitivas?', o: ['Interpretaciones automáticas y sesgadas de la realidad', 'Pensamientos negativos que siempre son falsos', 'Creencias irracionales sobre cómo deberían ser las cosas', 'Emociones intensas que no se pueden controlar'], e: 'Son formas sesgadas de interpretar lo que pasa. No siempre son falsas, y las creencias irracionales son el concepto de Ellis.', t: 'distorsiones-cognitivas' },
  { p: '"Me salió mal una vez: nunca me va a salir nada bien". ¿Qué distorsión es?', o: ['Generalización excesiva', 'Personalización', 'Falacia de recompensa divina', 'Minimización'], e: 'Arma una regla general a partir de un hecho aislado.', t: 'distorsiones-cognitivas' },
  { p: 'Ver todo en extremos, sin puntos intermedios, es…', o: ['Pensamiento dicotómico', 'Conclusión arbitraria', 'Abstracción selectiva', 'Maximización'], e: 'Es el pensamiento dicotómico, o "todo o nada".', t: 'distorsiones-cognitivas' },
  { p: 'Ver a dos personas conversando y suponer que hablan de uno es…', o: ['Personalización', 'Generalización excesiva', 'Pensamiento dicotómico', 'Filtraje'], e: 'La personalización es creer que lo que pasa alrededor tiene que ver con uno.', t: 'distorsiones-cognitivas' },
  { p: '¿Qué psiquiatra describió las distorsiones como parte de su terapia cognitiva?', o: ['Aaron Beck', 'John Bowlby', 'Jorge Barudy', 'Urie Bronfenbrenner'], e: 'Aaron Beck las describió como parte de la terapia cognitiva.', t: 'distorsiones-cognitivas' },
  { p: '¿Cuál es el primer paso para trabajar las distorsiones?', o: ['Identificarlas', 'Reemplazarlas por pensamientos positivos', 'Discutirlas con otra persona', 'Buscar de dónde vienen'], e: 'Primero hay que identificarlas, por ejemplo con el registro. Reemplazarlas por pensamientos positivos sin revisarlas no funciona.', t: 'distorsiones-cognitivas' },

  // ── Pensar correctamente ──
  { p: '¿Quién propuso el ABC de los problemas emocionales?', o: ['Albert Ellis', 'Aaron Beck', 'Matthew McKay', 'Paul MacLean'], e: 'Albert Ellis. Beck desarrolló la terapia cognitiva, McKay escribió sobre técnicas cognitivas y MacLean, sobre los tres cerebros.', t: 'pensar-correctamente' },
  { p: 'En el ABC de Ellis, ¿qué es la C?', o: ['La consecuencia: la reacción emocional', 'La causa real del problema', 'La creencia sobre lo que pasó', 'El cuestionamiento de la creencia'], e: 'La C es la consecuencia. La B es la creencia y la D, el cuestionamiento.', t: 'pensar-correctamente' },
  { p: 'En el ABC de Ellis, ¿qué es la A?', o: ['El acontecimiento activador', 'La creencia sobre lo que pasó', 'La reacción emocional', 'La solución del problema'], e: 'Parece producir la reacción emocional, pero no es su causa.', t: 'pensar-correctamente' },
  { p: 'Según la guía, ¿qué nos pasa si intentamos que todo el mundo nos quiera y apruebe lo que hacemos?', o: ['Nos volvemos más inseguros y dependientes', 'Ganamos aceptación, aunque cueste esfuerzo', 'Evitamos conflictos y estamos más tranquilos', 'Mejoran nuestros vínculos con los demás'], e: 'Buscar la aprobación de todos nos vuelve inseguros y dependientes de la mirada ajena.', t: 'pensar-correctamente' },
  { p: 'Frente al mito de que hay que conseguir todo lo que uno se propone, la guía señala que…', o: ['Nadie hace todo bien, y el perfeccionismo da ansiedad', 'Con suficiente esfuerzo, se puede lograr casi todo', 'Conviene ponerse metas bajas para no fracasar', 'El éxito depende de la fuerza de voluntad'], e: 'Nadie hace todo bien. Exigírselo genera ansiedad; bajar las metas para no fallar es otra forma de evitar.', t: 'pensar-correctamente' },
  { p: 'Cuando algo no sale como queremos, ¿qué propone la guía en vez de pensar que es una catástrofe?', o: ['Pensar “qué pena” y hacer algo útil', 'Aceptarlo sin sentir nada', 'Pensar que todo pasa por algo', 'Repetirse que no es para tanto'], e: 'Reconocer que es una pena, sin dramatizar, y hacer algo útil. No se trata de no sentir ni de minimizar.', t: 'pensar-correctamente' },

  // ── Teoría del apego ──
  { p: '¿Quién formuló la teoría del apego?', o: ['John Bowlby', 'Mary Ainsworth', 'Donald Winnicott', 'Harry Harlow'], e: 'John Bowlby. Ainsworth la amplió con la situación extraña y los estilos; Winnicott habló de la madre suficientemente buena; Harlow experimentó con monos.', t: 'teoria-del-apego' },
  { p: '¿Qué estilo de apego se asocia a un cuidador que responde rápido y con afecto?', o: ['Seguro', 'Ambivalente', 'Evitativo', 'Desorganizado'], e: 'El apego seguro favorece la estabilidad emocional, la iniciativa y la confianza en uno mismo.', t: 'teoria-del-apego' },
  { p: 'Cuando un niño confía en que su cuidador va a estar disponible…', o: ['Siente menos miedo y se anima a explorar', 'Se vuelve más dependiente de su cuidador', 'Lo necesita cada vez menos seguido', 'Se apega más a otras personas'], e: 'La confianza en una base segura permite explorar. La seguridad no genera dependencia: la favorece la inseguridad.', t: 'teoria-del-apego' },
  { p: 'Quien cuida rechaza o ignora las necesidades del bebé. ¿Qué estilo se asocia?', o: ['Evitativo', 'Seguro', 'Ambivalente', 'Desorganizado'], e: 'En el apego evitativo, el bebé aprende a reprimir sus sentimientos y a evitar el contacto para no ser rechazado.', t: 'teoria-del-apego' },
  { p: 'Según la guía, ¿qué describen los estilos de apego?', o: ['Tendencias que pueden cambiar', 'Rasgos fijos que se forman en la infancia', 'Rasgos que se heredan de los padres', 'Diagnósticos de trastornos del vínculo'], e: 'Son tendencias, no etiquetas: pueden cambiar con vínculos nuevos (seguridad ganada).', t: 'teoria-del-apego' },
  { p: 'Al nacer, ¿dónde aprendemos a regular nuestras emociones?', o: ['En el vínculo con quien nos cuida', 'Solos, a medida que madura el cerebro', 'En la escuela, con pares y docentes', 'En la adolescencia, con los amigos'], e: 'Primero se aprenden en el vínculo con quien cuida, que calma y ayuda a ponerle nombre a lo que se siente.', t: 'teoria-del-apego' },

  // ── Personalidad ──
  { p: '¿Qué estilo de personalidad desconfía y atribuye malas intenciones a los demás?', o: ['Paranoide', 'Narcisista', 'Por dependencia', 'Obsesivo-compulsiva'], e: 'Atribuye motivos ocultos a los demás; su estrategia es la vigilancia permanente.', t: 'personalidad' },
  { p: '¿Qué estilo de personalidad se ve como especial y por encima de las reglas?', o: ['Narcisista', 'Paranoide', 'Por evitación', 'Esquizoide'], e: 'La clave del estilo narcisista es la “autoexaltación”.', t: 'personalidad' },
  { p: '¿Qué teme sobre todo la personalidad por dependencia?', o: ['El rechazo o el abandono', 'Los errores y el desorden', 'El acercamiento excesivo', 'Perder su estatus'], e: 'Se ve desvalida y necesita unirse a alguien más fuerte; su amenaza es el rechazo o el abandono.', t: 'personalidad' },
  { p: '¿Qué estrategia usa el estilo esquizoide?', o: ['Mantener la distancia', 'Buscar admiración', 'Subordinarse para agradar', 'Vigilar a los demás'], e: 'Se ve autosuficiente y vive el acercamiento excesivo como amenaza.', t: 'personalidad' },
  { p: '¿En qué autores se basa la guía para describir los estilos de personalidad?', o: ['Beck y Freeman', 'Beck y Ellis', 'McKay y Davis', 'Bowlby y Ainsworth'], e: 'Beck y Freeman, en Terapia cognitiva de los trastornos de personalidad. Ellis trabajó las creencias irracionales y Bowlby y Ainsworth, el apego.', t: 'personalidad' },

  // ── El duelo ──
  { p: 'Según Bowlby, ¿cuántas fases tiene el duelo?', o: ['Cuatro', 'Cinco', 'Tres', 'Siete'], e: 'Bowlby describe cuatro fases. Las cinco etapas son el modelo de Kübler-Ross, que es otro.', t: 'duelo' },
  { p: 'Durante el duelo, el enojo…', o: ['Es normal: busca recuperar el vínculo', 'Indica que el duelo se complicó', 'Es la primera fase del duelo', 'Es una señal de depresión'], e: 'El enojo es parte normal del duelo. La primera fase, según Bowlby, es el embotamiento.', t: 'duelo' },
  { p: '¿Cuál es la primera fase del duelo según Bowlby?', o: ['Embotamiento', 'Anhelo y búsqueda', 'Desorganización y desesperanza', 'Reorganización'], e: 'El embotamiento dura desde unas horas hasta una semana.', t: 'duelo' },
  { p: 'Si alguien en duelo tiene ideas de quitarse la vida, ¿qué hay que hacer?', o: ['Pedir ayuda profesional enseguida', 'Esperar a ver si se le pasa con el tiempo', 'Respetar su espacio y no preguntar', 'No mencionar el tema para no darle ideas'], e: 'Hay que pedir ayuda enseguida (Línea 135). Preguntar no da ideas: abre la puerta a que la persona hable.', t: 'duelo' },
  { p: 'Según Firth, ¿a quiénes benefician los rituales funerarios?', o: ['A quienes quedan', 'A quien murió', 'A la comunidad religiosa', 'A quienes organizan el ritual'], e: 'Los rituales ayudan a quienes quedan a aceptar la pérdida y a sentirse acompañados.', t: 'duelo' },
  { p: '¿En qué fase la persona empieza a darle una nueva forma a su vida?', o: ['Reorganización', 'Embotamiento', 'Anhelo y búsqueda', 'Desorganización y desesperanza'], e: 'En la reorganización la persona piensa en su nueva situación y empieza a darle otra forma a su vida.', t: 'duelo' },

  // ── Habilidades interpersonales ──
  { p: '¿Cuál de estas es una de las habilidades interpersonales más importantes?', o: ['Saber decir que no', 'Saber convencer a los demás', 'Ceder para mantener la paz', 'Tener siempre una respuesta'], e: 'Saber decir que no permite cuidar lo propio sin romper el vínculo. Ceder siempre es la conducta pasiva, y convencer no es lo mismo que comunicar.', t: 'habilidades-interpersonales' },
  { p: '¿Qué implica prestar atención en una conversación?', o: ['Estar en el aquí y ahora', 'Pensar qué vamos a responder', 'Asentir para que el otro siga', 'Buscar la solución mientras habla'], e: 'Prestar atención es estar presente. Preparar la respuesta o buscar soluciones mientras el otro habla nos saca de la conversación.', t: 'habilidades-interpersonales' },
  { p: 'Según la guía, ¿de dónde surge la conducta agresiva?', o: ['De la necesidad de controlar', 'De renunciar a lo que uno necesita', 'De prestar demasiada atención al otro', 'De un exceso de asertividad'], e: 'Surge de un fuerte sentido de “cómo deberían ser las cosas” y de la necesidad de controlar, y destruye las relaciones. Renunciar a lo propio es la conducta pasiva.', t: 'habilidades-interpersonales' },
  { p: 'Decir “a ver si te entendí…” y repetir con otras palabras sirve para…', o: ['Comprobar que entendimos al otro', 'Mostrarle al otro que tiene razón', 'Ganar tiempo antes de responder', 'Corregir lo que el otro dijo mal'], e: 'Parafrasear sirve para comprobar que entendimos. Entender no es darle la razón.', t: 'habilidades-interpersonales' },
  { p: '¿Cuál es el primer paso del esquema para resolver problemas?', o: ['Reconocer el problema', 'Pensar varias opciones', 'Elegir la mejor opción', 'Buscar al responsable'], e: 'Primero se reconoce el problema; después se piensan opciones, se elige, se aplica y se evalúa.', t: 'habilidades-interpersonales' },
  { p: 'Mirar a los ojos, sonreír y usar un tono cálido es parte de…', o: ['Hablar con el cuerpo', 'Prestar atención', 'Parafrasear', 'Pedir con claridad'], e: 'Es la comunicación con el cuerpo. Las otras también son claves de comunicación, pero se refieren a escuchar o a lo que se dice.', t: 'habilidades-interpersonales' },

  // ── Límites y negociación ──
  { p: 'Según la guía, ¿para qué sirve la capacidad de decir “no”?', o: ['Para mostrar qué necesitamos y qué no', 'Para que los demás dejen de pedirnos cosas', 'Para no tener que negociar con nadie', 'Para ganar las discusiones'], e: 'Decir que no muestra nuestras necesidades y cuida el vínculo. No busca cortar los pedidos ni evitar negociar.', t: 'limites-y-negociacion' },
  { p: '¿Cuál es la esencia de un límite?', o: ['Decir que no', 'Explicar por qué no', 'Ofrecer una alternativa', 'Pedir disculpas'], e: 'La esencia es el “no”. Dar una razón o una alternativa puede ayudar, pero no es obligatorio, y pedir disculpas debilita el límite.', t: 'limites-y-negociacion' },
  { p: 'Si solemos decir que sí sin pensar, la guía aconseja…', o: ['Darse tiempo antes de responder', 'Decir que no a todo por un tiempo', 'Pedir disculpas antes de negarse', 'Responder con una excusa'], e: 'Darse tiempo (“dejame pensarlo”) permite decidir sin presión.', t: 'limites-y-negociacion' },
  { p: 'En una negociación, ¿qué lugar ocupan las necesidades del otro?', o: ['Valen lo mismo que las propias', 'Se escuchan para encontrar su punto débil', 'Van primero, para que el otro ceda después', 'Cuentan si coinciden con las mías'], e: 'En una negociación justa, las necesidades de los dos tienen el mismo valor.', t: 'limites-y-negociacion' },
  { p: '¿Cuál es el primer paso de la negociación?', o: ['Saber qué es lo que se quiere', 'Escuchar el punto de vista del otro', 'Hacer una propuesta', 'Llegar a un compromiso'], e: 'Primero hay que tener claro qué se quiere. Escuchar al otro, proponer y llegar a un compromiso vienen después.', t: 'limites-y-negociacion' },
  { p: 'En una negociación, entender el punto de vista del otro…', o: ['No significa estar de acuerdo', 'Obliga a ceder en algo a cambio', 'Debilita la propia posición', 'Es el último paso, antes del acuerdo'], e: 'Entender no es darle la razón ni ceder. Escuchar al otro es uno de los primeros pasos.', t: 'limites-y-negociacion' },

  // ── Nuevas familias ──
  { p: 'Para Barudy, la familia es…', o: ['Un sistema abierto, en relación con la sociedad', 'Un ámbito privado, separado de lo público', 'Una institución que cambia poco con el tiempo', 'Un vínculo basado en los lazos de sangre'], e: 'Barudy la ve como un sistema abierto: lo que pasa adentro refleja lo que pasa afuera.', t: 'nuevas-familias' },
  { p: 'Uno de los adultos de la pareja tiene un hijo de una relación anterior. ¿Qué familia forman?', o: ['Ensamblada', 'Nuclear', 'Extensa', 'Monoparental'], e: 'Es una familia ensamblada. Nuclear es una pareja con o sin hijos en común; extensa incluye a otros parientes.', t: 'nuevas-familias' },
  { p: 'Una familia que incluye a abuelos, tíos u otros parientes es…', o: ['Extensa', 'Nuclear', 'Ensamblada', 'Monoparental'], e: 'La familia extensa incluye otros parientes y también vínculos afectivos sin lazo de sangre.', t: 'nuevas-familias' },
  { p: '¿Qué ley argentina reconoce el matrimonio entre personas del mismo género?', o: ['La Ley 26.618', 'La Ley 26.743', 'La Ley 23.515', 'La Ley 26.485'], e: 'La 26.618 (2010). La 26.743 es la de identidad de género; la 23.515, la de divorcio; la 26.485, la de violencia contra las mujeres.', t: 'nuevas-familias' },
  { p: 'En una separación, ¿qué es lo que más daña a hijas e hijos?', o: ['El conflicto sostenido entre los adultos', 'La separación en sí misma', 'Tener que mudarse a otra casa', 'Que uno de los padres forme otra pareja'], e: 'Lo que más daña es el conflicto que no termina. La separación duele, pero doloroso no es lo mismo que enfermante.', t: 'nuevas-familias' },
  { p: 'Un niño cree que sus padres se separaron por su culpa. ¿Qué conviene hacer?', o: ['Decirle con claridad que no es su culpa', 'Esperar a que pregunte, para no angustiarlo', 'Explicarle en detalle por qué se separaron', 'Decirle que ya lo va a entender de grande'], e: 'Hay que decirle claramente que no es su culpa, con palabras simples y sin detalles del conflicto de los adultos.', t: 'nuevas-familias' },

  // ── Relajación avanzada ──
  { p: '¿Qué imagen ayuda a hacer la respiración diafragmática?', o: ['Llenar una cantimplora desde abajo', 'Inflar un globo con fuerza', 'Llenar los pulmones desde arriba', 'Contener el aire unos segundos'], e: 'El aire entra desde abajo, como el agua en una cantimplora: primero se llena la panza.', t: 'relajacion-avanzada' },
  { p: 'En la respiración diafragmática, ¿qué mano debería subir al tomar aire?', o: ['La que está sobre la panza', 'La que está sobre el pecho', 'Las dos por igual', 'Ninguna: el cuerpo queda quieto'], e: 'Sube la mano de la panza y la del pecho casi no se mueve. Si sube el pecho, la respiración es superficial.', t: 'relajacion-avanzada' },
  { p: 'En la relajación con palabra clave, ¿cuándo se dice la palabra?', o: ['Cada vez que se suelta el aire', 'Cada vez que se toma aire', 'Al tensar cada músculo', 'Al final de cada escena'], e: 'Se dice o se piensa al soltar el aire, mientras se afloja el cuerpo.', t: 'relajacion-avanzada' },
  { p: 'En la relajación con palabra clave, ¿cuántas veces seguidas se repite la palabra en cada práctica?', o: ['Diez', 'Tres', 'Cinco', 'Siete'], e: 'Diez veces seguidas, en cada exhalación. Para que la respuesta se vuelva automática hay que practicar a diario durante las semanas siguientes.', t: 'relajacion-avanzada' },
];
